#define MAXN 55
#define MAXM 8
#define MAXLINES (2*MAXM + 2)
#define INF 1000000000

typedef struct {
    int mask;
    int cnt;
} LineMask;

typedef struct {
    int value;
    int owner;
} Pair;

static int N, M;
static int card[MAXN][MAXM][MAXM];
static int vals[MAXN * MAXM * MAXM];
static int valCnt;

static int lineMasks[MAXN][MAXLINES];
static int lineCnt[MAXN];

static int uniqVals[MAXN][MAXM * MAXM];
static int uniqCnt[MAXN];

static int bestRank[MAXN][1 << (MAXM * MAXM)];
static char vis[MAXN][1 << (MAXM * MAXM)];

static int cmp_int(const void *a, const void *b) {
    int x = *(const int*)a, y = *(const int*)b;
    return (x > y) - (x < y);
}

static int cmp_pair(const void *a, const void *b) {
    const Pair *x = (const Pair*)a, *y = (const Pair*)b;
    if (x->value != y->value) return (x->value > y->value) - (x->value < y->value);
    return x->owner - y->owner;
}

static int lower_bound_int(int *arr, int n, int x) {
    int l = 0, r = n;
    while (l < r) {
        int mid = (l + r) >> 1;
        if (arr[mid] < x) l = mid + 1;
        else r = mid;
    }
    return l;
}

/* Compute earliest announcement count needed for player p to have bingo,
   given allowed announced numbers are exactly those in subset mask of uniqVals[p].
   Return minimal rank among all line completions, or INF if impossible. */
static int solve_player(int p, int mask) {
    if (vis[p][mask]) return bestRank[p][mask];
    vis[p][mask] = 1;

    int ans = INF;
    for (int li = 0; li < lineCnt[p]; li++) {
        int lm = lineMasks[p][li];
        if ((mask & lm) == lm) {
            int mx = 0;
            for (int k = 0; k < uniqCnt[p]; k++) {
                if (lm & (1 << k)) {
                    int v = uniqVals[p][k];
                    int rk = lower_bound_int(vals, valCnt, v) + 1;
                    if (rk > mx) mx = rk;
                }
            }
            if (mx < ans) ans = mx;
        }
    }

    if (ans != INF) {
        bestRank[p][mask] = ans;
        return ans;
    }

    bestRank[p][mask] = INF;
    return INF;
}

int main(void) {
    if (scanf("%d %d", &N, &M) != 2) return 0;

    valCnt = 0;
    for (int i = 0; i < N; i++) {
        for (int r = 0; r < M; r++) {
            for (int c = 0; c < M; c++) {
                scanf("%d", &card[i][r][c]);
                vals[valCnt++] = card[i][r][c];
            }
        }
    }

    qsort(vals, valCnt, sizeof(int), cmp_int);
    int nv = 0;
    for (int i = 0; i < valCnt; i++) {
        if (i == 0 || vals[i] != vals[i - 1]) vals[nv++] = vals[i];
    }
    valCnt = nv;

    for (int p = 0; p < N; p++) {
        Pair tmp[MAXM * MAXM];
        int tcnt = 0;
        for (int r = 0; r < M; r++) {
            for (int c = 0; c < M; c++) {
                tmp[tcnt].value = card[p][r][c];
                tmp[tcnt].owner = r * M + c;
                tcnt++;
            }
        }
        qsort(tmp, tcnt, sizeof(Pair), cmp_pair);

        uniqCnt[p] = 0;
        int posMap[MAXM * MAXM];
        int i = 0;
        while (i < tcnt) {
            int j = i;
            while (j < tcnt && tmp[j].value == tmp[i].value) j++;
            int idx = uniqCnt[p]++;
            uniqVals[p][idx] = tmp[i].value;
            for (int k = i; k < j; k++) posMap[tmp[k].owner] = idx;
            i = j;
        }

        lineCnt[p] = 0;
        for (int r = 0; r < M; r++) {
            int mask = 0;
            for (int c = 0; c < M; c++) mask |= 1 << posMap[r * M + c];
            lineMasks[p][lineCnt[p]++] = mask;
        }
        for (int c = 0; c < M; c++) {
            int mask = 0;
            for (int r = 0; r < M; r++) mask |= 1 << posMap[r * M + c];
            lineMasks[p][lineCnt[p]++] = mask;
        }
        int mask = 0;
        for (int d = 0; d < M; d++) mask |= 1 << posMap[d * M + d];
        lineMasks[p][lineCnt[p]++] = mask;

        mask = 0;
        for (int d = 0; d < M; d++) mask |= 1 << posMap[d * M + (M - 1 - d)];
        lineMasks[p][lineCnt[p]++] = mask;
    }

    int prev = 0;
    int answer = 0;

    for (int p = 0; p < N; p++) {
        int U = uniqCnt[p];
        int total = 1 << U;
        int best = INF;

        memset(vis[p], 0, total * sizeof(char));

        for (int mask = 0; mask < total; mask++) {
            int rank = solve_player(p, mask);
            if (rank == INF) continue;
            if (rank > prev && rank < best) best = rank;
        }

        if (best == INF) {
            printf("0\n");
            return 0;
        }
        prev = best;
        answer = best;
    }

    printf("%d\n", answer);
    return 0;
}

