int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<vector<vector<int>>> card(N, vector<vector<int>>(M, vector<int>(M)));
    int maxNum = 0;

    for (int p = 0; p < N; ++p) {
        for (int i = 0; i < M; ++i) {
            for (int j = 0; j < M; ++j) {
                cin >> card[p][i][j];
                maxNum = max(maxNum, card[p][i][j]);
            }
        }
    }

    // For each player, collect all bingo lines as bitmasks over numbers.
    // Number values are assumed to be positive integers; compress by maxNum.
    vector<vector<unsigned long long>> linesMask(N);
    int W = (maxNum + 64) / 64;

    auto makeMask = [&](const vector<int>& nums) {
        vector<unsigned long long> mask(W, 0);
        for (int x : nums) {
            int idx = x / 64;
            int bit = x % 64;
            mask[idx] |= (1ULL << bit);
        }
        return mask;
    };

    vector<vector<vector<unsigned long long>>> playerLines(N);

    for (int p = 0; p < N; ++p) {
        vector<vector<unsigned long long>> lines;

        // rows
        for (int i = 0; i < M; ++i) {
            vector<int> nums;
            for (int j = 0; j < M; ++j) nums.push_back(card[p][i][j]);
            lines.push_back(makeMask(nums));
        }
        // cols
        for (int j = 0; j < M; ++j) {
            vector<int> nums;
            for (int i = 0; i < M; ++i) nums.push_back(card[p][i][j]);
            lines.push_back(makeMask(nums));
        }
        // main diagonal
        {
            vector<int> nums;
            for (int i = 0; i < M; ++i) nums.push_back(card[p][i][i]);
            lines.push_back(makeMask(nums));
        }
        // anti diagonal
        {
            vector<int> nums;
            for (int i = 0; i < M; ++i) nums.push_back(card[p][i][M - 1 - i]);
            lines.push_back(makeMask(nums));
        }

        playerLines[p] = move(lines);
    }

    // dp over chosen winning lines:
    // Let S_i be the set of announced numbers after making player i win.
    // To ensure player i wins before player i+1, at stage i+1 we must choose a line L of player i+1
    // such that L is NOT subset of S_i, and then S_{i+1} = S_i union L.
    //
    // We want minimize |S_N|.
    //
    // State compression by keeping only Pareto-optimal masks for each player.
    // Since constraints are not provided in statement text, we use exact DP with dominance pruning.

    vector<vector<unsigned long long>> states;
    // Initial: choose any winning line for player 0
    states = playerLines[0];

    auto popcountMask = [&](const vector<unsigned long long>& a) {
        int s = 0;
        for (auto x : a) s += __builtin_popcountll(x);
        return s;
    };

    auto subsetOf = [&](const vector<unsigned long long>& a, const vector<unsigned long long>& b) {
        // a subset of b ?
        for (int i = 0; i < W; ++i) {
            if ((a[i] & ~b[i]) != 0) return false;
        }
        return true;
    };

    auto uniteMask = [&](const vector<unsigned long long>& a, const vector<unsigned long long>& b) {
        vector<unsigned long long> c(W);
        for (int i = 0; i < W; ++i) c[i] = a[i] | b[i];
        return c;
    };

    auto equalMask = [&](const vector<unsigned long long>& a, const vector<unsigned long long>& b) {
        return a == b;
    };

    auto prune = [&](vector<vector<unsigned long long>>& vec) {
        // Remove duplicates
        sort(vec.begin(), vec.end());
        vec.erase(unique(vec.begin(), vec.end()), vec.end());

        // Remove dominated supersets:
        // if A subset B, then B is never better than A.
        vector<int> ord(vec.size());
        iota(ord.begin(), ord.end(), 0);
        sort(ord.begin(), ord.end(), [&](int i, int j) {
            int ci = popcountMask(vec[i]), cj = popcountMask(vec[j]);
            if (ci != cj) return ci < cj;
            return vec[i] < vec[j];
        });

        vector<vector<unsigned long long>> res;
        for (int id : ord) {
            bool dominated = false;
            for (auto& kept : res) {
                if (subsetOf(kept, vec[id])) {
                    dominated = true;
                    break;
                }
            }
            if (!dominated) res.push_back(vec[id]);
        }
        vec.swap(res);
    };

    prune(states);

    for (int p = 1; p < N; ++p) {
        vector<vector<unsigned long long>> nxt;
        for (auto& s : states) {
            for (auto& line : playerLines[p]) {
                // player p must not have already won before this stage
                if (subsetOf(line, s)) continue;
                nxt.push_back(uniteMask(s, line));
            }
        }
        prune(nxt);
        states.swap(nxt);
    }

    int ans = INT_MAX;
    for (auto& s : states) ans = min(ans, popcountMask(s));

    cout << ans << '\n';
    return 0;
}

