public class Main {
    static int N, M, U;
    static BitSet[][] playerLines; // [N][2M+2]
    static HashMap<Integer, Integer>[] memo;

    static int dfs(int idx, BitSet union) {
        if (idx == N) return 0;
        int key = union.hashCode();
        Integer got = memo[idx].get(key);
        if (got != null) return got;

        int best = Integer.MAX_VALUE / 4;
        for (BitSet line : playerLines[idx]) {
            BitSet tmp = (BitSet) line.clone();
            tmp.andNot(union);
            int added = tmp.cardinality();
            if (idx > 0 && added == 0) continue; // must contain at least one new number
            BitSet nu = (BitSet) union.clone();
            nu.or(line);
            int sub = dfs(idx + 1, nu);
            best = Math.min(best, added + sub);
        }
        memo[idx].put(key, best);
        return best;
    }

