        int[][][] cards = new int[N][M][M];
        HashMap<Integer, Integer> comp = new HashMap<>();
        int id = 0;
        for (int p = 0; p < N; p++) {
            for (int i = 0; i < M; i++) {
                for (int j = 0; j < M; j++) {
                    int x = fs.nextInt();
                    cards[p][i][j] = x;
                    if (!comp.containsKey(x)) comp.put(x, id++);
                }
            }
        }
        U = id;

        playerLines = new BitSet[N][2 * M + 2];
        for (int p = 0; p < N; p++) {
            int idx = 0;
            for (int i = 0; i < M; i++) {
                BitSet bs = new BitSet(U);
                for (int j = 0; j < M; j++) bs.set(comp.get(cards[p][i][j]));
                playerLines[p][idx++] = bs;
            }
            for (int j = 0; j < M; j++) {
                BitSet bs = new BitSet(U);
                for (int i = 0; i < M; i++) bs.set(comp.get(cards[p][i][j]));
                playerLines[p][idx++] = bs;
            }
            BitSet d1 = new BitSet(U);
            for (int i = 0; i < M; i++) d1.set(comp.get(cards[p][i][i]));
            playerLines[p][idx++] = d1;

            BitSet d2 = new BitSet(U);
            for (int i = 0; i < M; i++) d2.set(comp.get(cards[p][i][M - 1 - i]));
            playerLines[p][idx++] = d2;
        }

        memo = new HashMap[N];
        for (int i = 0; i < N; i++) memo[i] = new HashMap<>();

        int ans = dfs(0, new BitSet(U));
        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
